from datetime import date, timedelta
from typing import Dict, Set


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days: int = loan_days
        self.daily_fine: float = daily_fine

        # Set of registered books
        self.books: Set[str] = set()

        # Mapping of book_id -> (borrower_user_id, borrow_date)
        self.loans: Dict[str, tuple[str, date]] = {}

        # Mapping of user -> set of currently borrowed book_ids
        self.user_books: Dict[str, Set[str]] = {}

        # Mapping of user -> total unpaid fines
        self.fines: Dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book '{book_id}' does not exist in the library.")

        # Requirement 2: Borrowing a book that is currently borrowed raises ValueError.
        if book_id in self.loans:
            raise ValueError(f"Book '{book_id}' is currently borrowed.")

        user_current_books = self.user_books.get(user, set())

        # Requirement 1: A user with unpaid fines may still borrow books,
        # but may hold at most one book at a time.
        if self.unpaid_fines(user) > 0.0 and len(user_current_books) >= 1:
            raise ValueError(
                f"User '{user}' has unpaid fines and cannot borrow more than one book."
            )

        self.loans[book_id] = (user, day)
        self.user_books.setdefault(user, set()).add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        # Requirement 4: Returning a book that the user has not borrowed raises ValueError.
        if book_id not in self.loans or self.loans[book_id][0] != user:
            raise ValueError(f"User '{user}' has not borrowed book '{book_id}'.")

        _, borrow_date = self.loans.pop(book_id)
        self.user_books[user].remove(book_id)

        due_date = borrow_date + timedelta(days=self.loan_days)

        # Requirement 3: Saturdays and Sundays are not counted as days of delay.
        overdue_business_days = 0
        current_day = due_date + timedelta(days=1)
        while current_day <= day:
            # weekday(): Monday is 0 and Sunday is 6
            if current_day.weekday() < 5:
                overdue_business_days += 1
            current_day += timedelta(days=1)

        fine = overdue_business_days * self.daily_fine
        if fine > 0.0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines[user] = 0.0
```

